namespace ITG.Models.Entities;

// A self-assessment exam. Questions are generated by AI each time an attempt starts.
// Exams are for self-evaluation only and do not affect the roadmap or promotion.
// An employee sees the exams of their current position and of the position they are working towards.
public class Exam
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string? Description { get; set; }
    public string Category { get; set; } = string.Empty;

    public int DurationMinutes { get; set; } = 30;
    public int QuestionCount { get; set; } = 15;

    // Positions this exam is meant for (one exam can serve several positions)
    public ICollection<ExamPosition> ExamPositions { get; set; } = new List<ExamPosition>();

    public bool IsActive { get; set; } = true;
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    public ICollection<ExamAttempt> Attempts { get; set; } = new List<ExamAttempt>();
}
